scripts.script:
if (Macros.checkStance(actor, args)) {
    const source = thisItem.effects.getName("眼力");
    if (source) {
        await game.xjzl.api.effects.addEffect(actor, source.toObject());
        if(actor.token?.object) actor.showFloatyText("眼力+1", {fill: "#00FF00"});
    }
}

if (args.isBroken) {
    const rounds = Math.max(1, args.move.computedLevel || 1);
    const effectData = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "root"));
    effectData.duration = { rounds: rounds };
    await game.xjzl.api.effects.addEffect(args.target, effectData);
    ui.notifications.info(`${args.target.name} 被禁足！`);
}

if (args.isHit) {
    const effectData = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "root"));
    effectData.duration = { rounds: 3 };
    await game.xjzl.api.effects.addEffect(args.target, effectData);
}

if (args.isHit) {
    const effectData = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "unstable"));
    effectData.duration = { rounds: 1 };
    await game.xjzl.api.effects.addEffect(args.target, effectData);
}

if (args.isBroken) {
    // 1. 计算理论消减量
    const lvl = Math.max(1, args.move.computedLevel || 1);
    const drainAmount = 1 + (lvl - 1);

    // 2. 获取当前怒气 (已包含受击回怒)
    const currentRage = args.target.system.resources.rage.value;

    // 3. 检查本次是否因受击回复了怒气
    const gainedFromHit = args.damageResult?.rageGained ? 1 : 0;

    // 4. 计算“可被消减的存量” (排除掉刚刚挨打获得的那1点)
    const availableToDrain = Math.max(0, currentRage - gainedFromHit);

    // 5. 计算实际消减量
    const actualDrain = Math.min(availableToDrain, drainAmount);

    if (actualDrain > 0) {
        const newRage = Math.max(0, currentRage - actualDrain);
        await args.target.update({"system.resources.rage.value": newRage});

        // 使用自定义全局广播方法
        if (args.target.token?.object) {
            args.target.showFloatyText(`怒气 -${actualDrain}`, {fill: "#0000FF"});
        }
    }
}

if (args.isHit) {
    const source = thisItem.effects.getName("绵劲");
    if (source) {
        const effectData = source.toObject();
        effectData.duration = { rounds: 99 };
        await game.xjzl.api.effects.addEffect(actor, effectData);
    }
}

const amount = Math.floor(args.finalAmount);
if (amount > 0) {
    await args.target.applyHealing({ amount: amount, type: "huti", showScrolling: true });
}

const source = thisItem.effects.getName("残虹");
if (source) {
    await game.xjzl.api.effects.addEffect(actor, source.toObject());
}

if (args.isBroken) {
    const effectData = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "blind"));
    effectData.duration = { rounds: 3 };
    await game.xjzl.api.effects.addEffect(args.target, effectData);
    ui.notifications.info(`${args.target.name} 被致盲！`);
}

if (args.isHit) {
    await Macros.requestContest({
        attacker: actor,
        defender: args.target,
        type: 'duqi',
        label: '西子洗面 (请手动调整优势)',
        outcome: {
            win: {
                text: '对抗胜利：目标 [倒地]。',
                targetEffect: 'prone'
            },
            lose: { text: '对抗失败：未能击倒目标。' }
        }
    });
}

// 1. 计算总投掷次数
let diceCount = 1; // 基础1次

// 残虹效果: +1次
if (actor.effects.some(e => e.name === "残虹")) {
    diceCount += 1;
}

// 升级效果: 每级+1次 (从Lv2开始)
const lvl = Math.max(1, args.move.computedLevel || 1);
if (lvl > 1) {
    diceCount += (lvl - 1);
}

// 2. 只有当次数大于1时才介入
if (diceCount > 1) {
    // 投掷所有骰子
    const roll = await new Roll(`${diceCount}d20`).evaluate();

    // 播放动画
    if (game.dice3d) game.dice3d.showForRoll(roll, game.user, true);

    // 提取结果
    const results = roll.terms[0].results.map(r => r.result);
    const maxVal = Math.max(...results);
    const resultStr = results.join(", ");

    // 发送卡片
    const content = `<div class="xjzl-chat-card">
        <div class="card-content-wrapper" style="padding-left: 5px;">
            <div style="font-weight:bold; border-bottom:1px solid #ccc; margin-bottom:5px;">
                越女追魂 - 多重剑影
            </div>
            <p>招式特性：投掷 <b>${diceCount}</b> 次取最高。</p>
            <p>结果：[${resultStr}]</p>
            <p style="color:red; font-size:1.1em;">最高点数：<b>${maxVal}</b></p>
            <hr>
            <p style="font-size:0.8em; color:#666;">
              * 若此结果命中/暴击，请按住 <b>Shift</b> 点击[应用伤害]进行手动修正（勾选暴击）。
            </p>
        </div>
    </div>`;

    ChatMessage.create({
        user: game.user.id,
        speaker: ChatMessage.getSpeaker({actor: actor}),
        content: content
    });
}

const hasSun = actor.effects.some(e => e.name === "太阳");
const hasMoon = actor.effects.some(e => e.name === "太阴");
const hasShaoYang = actor.effects.some(e => e.name === "少阳");
const hasShaoYin = actor.effects.some(e => e.name === "少阴");
if (hasSun && hasMoon && hasShaoYang && hasShaoYin) {
    const source = thisItem.effects.getName("阴阳调和");
    if (source) await game.xjzl.api.effects.addEffect(actor, source.toObject());
}

const lvl = Math.max(1, args.move.computedLevel || 1);
const heal = 10 + (lvl - 1) * 10;
await actor.applyHealing({ amount: heal, type: "hp", showScrolling: true });

if (actor.effects.some(e => e.name === "阴阳调和")) {
    ChatMessage.create({
        content: `<div class="xjzl-chat-card"><p><b>推窗望月·阴阳：</b></p><p>可消耗反应动作，将目标朝你拉扯 <b>1米</b>。</p></div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

if (args.isHit && actor.effects.some(e => e.name === "阴阳调和")) {
    const lvl = Math.max(1, args.move.computedLevel || 1);
    const rounds = 1 + (lvl - 1);
    ChatMessage.create({
        content: `<div class="xjzl-chat-card"><h3>叶底藏花·阴阳</h3><p>请选择为 ${args.target.name} 添加的状态 (${rounds}回合):</p><p>需手动添加 [禁实] 或 [禁虚]</p></div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

if (Macros.checkStance(actor, args)) {
    if (args.attacker) {
        const neigongId = args.attacker.system.martial?.active_neigong;
        let element = "none";
        if (neigongId) {
            const ng = args.attacker.items.get(neigongId);
            if (ng) element = ng.system.element;
        }

        let buffs = [];
        if (element === "yang") buffs = ["太阳", "少阳"];
        else if (element === "yin") buffs = ["太阴", "少阴"];
        else if (element === "taiji") buffs = ["太阳", "太阴"]; 

        for (const name of buffs) {
            const source = thisItem.effects.getName(name);
            if(source) await game.xjzl.api.effects.addEffect(actor, source.toObject());
        }
        if(buffs.length > 0) ui.notifications.info(`气象万千触发：获得 ${buffs.join(",")}`);
        else ui.notifications.warn("气象万千：无法识别对方内功属性，请手动添加四象状态");
    }
}

if (actor.effects.some(e => e.name === "阴阳调和")) {
    const lvl = Math.max(1, move.computedLevel || 1);
    // 查找禁足 (root/jinzu)
    const root = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "root"));
    if (root) {
        root.duration = { rounds: 1 + (lvl - 1) };
        root.origin = item.uuid;
        await game.xjzl.api.effects.addEffect(args.target, root);
        ui.notifications.info(`${args.target.name} 被动静方圆先行禁足！`);
    }
}

if (args.isHit) {
    const fengzhao = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "fengzhao"));
    if (fengzhao) {
        fengzhao.duration = { rounds: 1 };
        fengzhao.origin = item.uuid;
        await game.xjzl.api.effects.addEffect(args.target, fengzhao);
    }
}

if (!Macros.checkStance(actor, args)) return;

// 获取当前架招的 ID
const stanceId = actor.system.martial.stance;
// 在本武学中找到该招式数据以读取等级
const stanceMove = thisItem.system.moves.find(m => m.id === stanceId);

// 动态计算持续时间：基础1 + (等级-1) = 等级
const lvl = Math.max(1, stanceMove?.computedLevel || 1);
const rounds = lvl;

const effectData = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "chizhi"));
effectData.duration = { rounds: rounds };

await game.xjzl.api.effects.addEffect(args.attacker, effectData);
actor.showFloatyText("迟滞反击", {fill: "#00FFFF"});

// 获取当前选中的目标 (Attack阶段 args.target 未必存在，使用 game.user.targets)
const targets = Array.from(game.user.targets);
const lvl = Math.max(1, move.computedLevel || 1);
const perPoint = 5 * lvl;

let msgContent = "";

if (targets.length > 0) {
    targets.forEach(t => {
        const tActor = t.actor;
        if (!tActor) return;
        // 计算经脉开启数
        let openCount = 0;
        const standard = tActor.system.jingmai?.standard || {};
        for(const key in standard) { if(standard[key]) openCount++; }

        const totalHeal = openCount * perPoint;

        msgContent += `<div style="margin-bottom:5px; border-bottom:1px dashed #eee; padding-bottom:4px;">
            <strong>${t.name}</strong><br>
            已通经脉: ${openCount}<br>
            <span style="color:green">理论治疗: <b>${totalHeal}</b></span>
        </div>`;
    });
} else {
    msgContent = "<p>未选中目标。请手动检查友方经脉数。</p>";
}

ChatMessage.create({
    content: `<div class="xjzl-chat-card">
        <div class="card-header" style="border-bottom:1px solid #aaa; font-weight:bold; color:#27ae60; margin-bottom:5px;">
            <i class="fas fa-hand-holding-medical"></i> 友方推拿提示
        </div>
        <div style="padding:5px; padding-left:8px; font-size:0.9em; color:#444;">
            ${msgContent}
            <div style="margin-top:5px; font-size:0.8em; color:#666;">
                *若治疗，请手动消耗 1 点怒气。
            </div>
        </div>
    </div>`,
    speaker: ChatMessage.getSpeaker({actor: actor})
});

if (args.isBroken) {
    // 检查目标是否有禁足状态
    const isRooted = args.target.statuses.has("root") || args.target.xjzlStatuses.forceSpeedZero;

    if (isRooted) {
        ChatMessage.create({ 
            content: `<div class="xjzl-chat-card">
                <div style="padding:5px; padding-left:8px; background:rgba(255,200,0,0.1); border:1px solid #e67e22; border-radius:4px;">
                    <h3 style="color:#d35400; margin:0;">平指劲·追击触发</h3>
                    <p style="font-size:0.9em;">目标处于禁足且架招被破。</p>
                    <p>请手动消耗反应动作，再次释放此招，或发起[点穴]检定。</p>
                </div>
            </div>`, 
            speaker: ChatMessage.getSpeaker({actor: actor}) 
        });
    }
}

if (args.isHit) {
    let openCount = 0;
    const standard = args.target.system.jingmai.standard;
    for(const key in standard) { if(standard[key]) openCount++; }

    const dc = 11 + openCount;

    // 获取系统点穴状态模板
    const effectData = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "dianxue"));
    effectData.duration = { rounds: 1 };
    // 将DC写入描述，方便查看
    effectData.description = `冲穴难度: ${dc}`;

    await game.xjzl.api.effects.addEffect(args.target, effectData);
    ui.notifications.info(`${args.target.name} 被点穴 (DC ${dc})`);
}

// 1. 计算治疗量
const skillVal = actor.system.skills.liaoshang.total;
const lvl = Math.max(1, move.computedLevel || 1);
const bonus = (lvl - 1) * 10;
const totalHeal = skillVal + bonus;

// 执行治疗
await args.target.applyHealing({ amount: totalHeal, type: "hp", showScrolling: true });

// 2. 应用云霞Buff
const source = thisItem.effects.getName("云霞");
if (source) {
    const effectData = source.toObject();
    delete effectData._id;
    effectData.origin = thisItem.uuid;
    effectData.duration = { rounds: 3 };
    await game.xjzl.api.effects.addEffect(args.target, effectData);
}

if (Macros.checkStance(actor, args)) {
    // 额外增加1点怒气 (系统默认受击/格挡可能会回怒，这里是额外的)
    const currentRage = actor.system.resources.rage.value;
    const maxRage = actor.system.resources.rage.max;
    if (currentRage < maxRage) {
        await actor.update({"system.resources.rage.value": currentRage + 1});
        actor.showFloatyText("怒气 +1", {fill: "#0000FF"});
    }

    // 获得离苦
    const source = thisItem.effects.getName("离苦");
    if (source) {
        const effectData = source.toObject();
        delete effectData._id;
        effectData.origin = thisItem.uuid;
        await game.xjzl.api.effects.addEffect(actor, effectData);
    }
}

// 获取敌我态度 (1: 友善, 0: 中立, -1: 敌对)
const getDisp = (a) => {
    if (a.token) return a.token.disposition;
    if (a.prototypeToken) return a.prototypeToken.disposition;
    return 0;
};

const actorDisp = getDisp(actor);
const targetDisp = getDisp(args.target);

// 判定逻辑: 相同 disposition 视为友方 
if (actorDisp === targetDisp) {
    args.config.amount = 0; // 伤害置零
    args.config.ignoreBlock = true; // 不跳格挡字样
    args.config.ignoreDefense = true;
}

const getDisp = (a) => {
    if (a.token) return a.token.disposition;
    if (a.prototypeToken) return a.prototypeToken.disposition;
    return 0;
};

const actorDisp = getDisp(actor);
const targetDisp = getDisp(args.target);

if (actorDisp === targetDisp) {
    // 计算治疗量: (疗伤*2) + (等级-1)*10
    const skillVal = actor.system.skills.liaoshang.total;
    const lvl = Math.max(1, args.move.computedLevel || 1);
    const bonus = (lvl - 1) * 10;
    const heal = (skillVal * 2) + bonus;

    await args.target.applyHealing({ amount: heal, type: "hp", showScrolling: true });
}

// 每次出招后(HIT_ONCE)消耗一层，排除架招本身
if (args.move.type !== "stance") {
    await game.xjzl.api.effects.removeEffect(actor, "liku", 1);
}

const lvl = Math.max(1, move.computedLevel || 1);
const bonusDmg = 5 + (lvl - 1) * 5;
const confirm = await foundry.applications.api.DialogV2.confirm({
    window: { title: "蓄力释放确认" },
    content: `<p>是否消耗 <b>蓄力动作</b> 释放此招？</p><p>释放距离 +2，伤害 <b>+${bonusDmg}</b></p>`,
    yes: { label: `蓄力释放 (+${bonusDmg})`, icon: "fas fa-fist-raised" },
    no: { label: "主要动作", icon: "fas fa-times" }
});
if (confirm) {
    args.flags.damageResult.damage += bonusDmg;
    args.flags.damageResult.breakdown += `\n+ 蓄力释放: ${bonusDmg}`;
    ui.notifications.info(`已消耗蓄力动作，招式伤害增强！`);
}

if (args.isBroken) {
    const content = `<div class="xjzl-chat-card" style="padding-left: 5px;"><div style="border-left: 4px solid #d35400; background: rgba(211, 84, 0, 0.05); padding: 5px;"><div style="font-weight:bold; color:#d35400; font-size:1.1em;"><i class="fas fa-wind"></i> 击飞！</div><div style="font-size:0.9em; margin-top:3px; color:#555;"><b>${args.target.name}</b> 的架招被分花扬柳击破，被击飞 <b>1 米</b>！</div></div></div>`;
    ChatMessage.create({ content: content, speaker: ChatMessage.getSpeaker({actor: actor}) });
}

if (Macros.checkStance(actor, args)) {
    const stanceId = actor.system.martial.stance;
    const moveData = thisItem.system.moves.find(m => m.id === stanceId);
    const lvl = Math.max(1, moveData?.computedLevel || 1);
    const rounds = 1 + (lvl - 1);
    const source = thisItem.effects.getName("皓腕");
    if (source) {
        const effectData = source.toObject();
        effectData.duration = { rounds: rounds };
        await game.xjzl.api.effects.addEffect(actor, effectData);
    }
}

if (!args.target.system.martial.stanceActive) {
    const content = `<div class="xjzl-chat-card" style="padding-left: 5px;"><div style="border-left: 4px solid #d35400; background: rgba(211, 84, 0, 0.05); padding: 5px;"><div style="font-weight:bold; color:#d35400; font-size:1.1em;"><i class="fas fa-wind"></i> 击飞！</div><div style="font-size:0.9em; margin-top:3px; color:#555;"><b>${args.target.name}</b> 因无架招保护，被剑风击飞 <b>1 米</b>！</div></div></div>`;
    ChatMessage.create({ content: content, speaker: ChatMessage.getSpeaker({actor: actor}) });
}

if (!args.target.system.martial.stanceActive) {
    const rootStatus = CONFIG.statusEffects.find(e => e.id === "root");
    if (rootStatus) {
        const rootData = foundry.utils.deepClone(rootStatus);
        rootData.duration = { rounds: 1 };
        await game.xjzl.api.effects.addEffect(args.target, rootData);
    }
    const fushenStatus = CONFIG.statusEffects.find(e => e.id === "fushen");
    if (fushenStatus) {
        const fushenData = foundry.utils.deepClone(fushenStatus);
        fushenData.duration = { rounds: 1 };
        await game.xjzl.api.effects.addEffect(args.target, fushenData);
    }
}

const targetDoc = args.target;
// 1. 移除限制状态
const toRemove = targetDoc.effects.filter(e => 
    e.statuses.has("unstable") || e.statuses.has("root") || 
    e.changes.some(c => c.key === "system.combat.speed" && Number(c.value) < 0)
).map(e => e.id);

if(toRemove.length > 0) await targetDoc.deleteEmbeddedDocuments("ActiveEffect", toRemove);

// 2. 自身增加速度 (仅对自己生效)
if (targetDoc.uuid === actor.uuid) {
    const lvl = Math.max(1, args.move.computedLevel || 1);
    const rounds = 1;
    const source = thisItem.effects.getName("白雪皑皑");
    if (source) {
        const effectData = source.toObject();
        effectData.duration = { rounds: rounds };
        // 基础2 + (等级-1)
        const spd = 2 + (lvl - 1);
        effectData.changes[0].value = String(spd);
        await game.xjzl.api.effects.addEffect(actor, effectData);
    }
}

if (args.isHit) {
    const lvl = Math.max(1, args.move.computedLevel || 1);
    const rounds = 1 + (lvl - 1);
    const source = thisItem.effects.getName("冻伤");
    if (source) {
        const effectData = source.toObject();
        delete effectData._id;
        effectData.origin = thisItem.uuid;
        effectData.duration = { rounds: rounds };
        await game.xjzl.api.effects.addEffect(args.target, effectData);
    }
}

const source = thisItem.effects.getName("飞鸿踏雪");
if (source) {
    const effectData = source.toObject();
    delete effectData._id;
    effectData.origin = thisItem.uuid;
    // 持续1回合
    effectData.duration = { rounds: 1 };
    await game.xjzl.api.effects.addEffect(actor, effectData);
}

if (args.target.effects.some(e => e.getFlag("xjzl-system", "slug") === "frostbite")) {
    args.flags.grantFeint += 1;
}

if (args.isBroken) {
    const lvl = Math.max(1, args.move.computedLevel || 1);
    // 基础10% + 升级5%
    const pct = 0.10 + (lvl - 1) * 0.05;
    const heal = Math.floor(actor.system.resources.hp.max * pct);
    await actor.applyHealing({ amount: heal, type: "hp", showScrolling: true });
}

if (args.target.effects.some(e => e.getFlag("xjzl-system", "slug") === "frostbite")) {
    const lvl = Math.max(1, args.move.computedLevel || 1);
    // 基础30 + 升级10
    args.config.amount += (30 + (lvl - 1) * 10);
}

const lvl = Math.max(1, args.move.computedLevel || 1);
const rounds = 1 + (lvl - 1);

// 获取敌我态度 (1: 友善, 0: 中立, -1: 敌对)
// 兼容 Actor 和 TokenDocument 数据结构
const getDisp = (a) => {
    if (a.token) return a.token.disposition; // TokenDocument (v11+)
    if (a.prototypeToken) return a.prototypeToken.disposition; // Actor
    return 0;
};

const actorDisp = getDisp(actor);
const targetDisp = getDisp(args.target);

// 判定逻辑: 相同 disposition 视为友方 
const isFriend = (actorDisp === targetDisp);

if (isFriend) {
    // 友方：凝霜
    const bonus = 5 + (lvl - 1) * 5;
    const source = thisItem.effects.getName("凝霜");
    if (source) {
        const effectData = source.toObject();
        delete effectData._id;
        effectData.origin = thisItem.uuid;
        effectData.duration = { rounds: rounds };
        effectData.description = `招式伤害+${bonus}，手动视为阴属性`;
        effectData.changes[0].value = String(bonus);
        await game.xjzl.api.effects.addEffect(args.target, effectData);
        ui.notifications.info(`${args.target.name} 获得 [凝霜]`);
    }
} else {
    // 敌方：下盘不稳
    const unstable = CONFIG.statusEffects.find(e => e.id === "unstable");
    if (unstable) {
        const effectData = foundry.utils.deepClone(unstable);
        effectData.duration = { rounds: rounds };
        effectData.origin = thisItem.uuid;
        await game.xjzl.api.effects.addEffect(args.target, effectData);
        ui.notifications.info(`${args.target.name} 下盘不稳`);
    }
}

if (args.isHit) {
    // 1. 检查是否已有冻伤 (触发眩晕)
    if (args.target.effects.some(e => e.getFlag("xjzl-system", "slug") === "frostbite")) {
        // 使用 xuanyun ID
        const xuanyun = CONFIG.statusEffects.find(e => e.id === "xuanyun");
        if (xuanyun) {
            const effectData = foundry.utils.deepClone(xuanyun);
            effectData.duration = { rounds: 1 };
            effectData.origin = thisItem.uuid;
            await game.xjzl.api.effects.addEffect(args.target, effectData);
            ui.notifications.info(`${args.target.name} 伤上加霜，陷入眩晕！`);
        }
    }

    // 2. 无论如何都施加冻伤 (刷新或叠加)
    const source = thisItem.effects.getName("冻伤");
    if (source) {
        const effectData = source.toObject();
        delete effectData._id;
        effectData.origin = thisItem.uuid;
        effectData.duration = { rounds: 99 };
        await game.xjzl.api.effects.addEffect(args.target, effectData);
    }
}

if (!args.isHit) return;

// 1. 防刷屏
if (actor.effects.some(e => e.name === "神虹")) return;

// 2. 读取并动态修改神虹数值
const sourceAe = thisItem.effects.getName("神虹");
let effectData = null;

if (sourceAe) {
    effectData = sourceAe.toObject();
    delete effectData._id;
    effectData.origin = thisItem.uuid;

    // 计算动态加成: 基础1 + (等级-1) = 等级
    const lvl = Math.max(1, move.computedLevel || 1);
    const bonus = lvl;

    effectData.changes.forEach(c => {
        if (c.key === "system.combat.xuzhao" || c.key === "system.combat.kanpo") {
            c.value = String(bonus);
        }
    });
    effectData.description += ` (当前虚招加成: +${bonus})`;
}

// 3. 发起自动化对抗
await Macros.requestContest({
    attacker: actor,
    defender: args.target,
    type: "sword",
    label: "袁公试剑 - 剑术对抗",
    outcome: {
        win: {
            text: "剑气冲霄！获胜获得 [神虹]。",
            selfEffect: effectData
        },
        lose: {
            text: "剑意被阻。"
        }
    }
});

if (args.isBroken) {
    ChatMessage.create({
        content: `<div class="xjzl-chat-card"><div class="card-content-wrapper"><p style="color:darkred; font-weight:bold;"><i class="fas fa-bolt"></i> 击破架招！</p><p>你可以消耗反应动作，对 3 米内的另一个敌人再施展一次【追形逐影】，且该次虚招对抗的 D20 <b>必定为 20</b>（请在随后的攻击弹窗中手动修改骰值，或勾选单体必中）。</p></div></div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

if (Macros.checkStance(actor, args) && args.attacker) {
    // 利用强大的 addEffect，支持直接传系统状态ID和层数
    await game.xjzl.api.effects.addEffect(args.attacker, "chanshou", 2);
    actor.showFloatyText("格挡反震！", { fill: "#FFA500" });
}

if (!args.isHit) return;
const hasShenhong = actor.effects.some(e => e.name === "神虹");
const lvl = Math.max(1, move.computedLevel || 1);

if (hasShenhong) {
    const extraReactions = lvl; // 升级: 再获得一个 (Lvl1=1, Lvl2=2...)
    ChatMessage.create({
        content: `<div class="xjzl-chat-card"><div class="card-content-wrapper"><p style="color:#2c3e50;"><b><i class="fas fa-bolt"></i> 纵横逆顺触发：</b></p><p>已处于[神虹]状态，下回合额外获得 <b>${extraReactions}</b> 个反应动作。</p></div></div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
} else {
    const sourceAe = thisItem.effects.getName("神虹");
    let effectData = null;
    if (sourceAe) {
        effectData = sourceAe.toObject();
        delete effectData._id;
        effectData.origin = thisItem.uuid;
        const bonus = lvl;
        effectData.changes.forEach(c => {
            if (c.key === "system.combat.xuzhao" || c.key === "system.combat.kanpo") c.value = String(bonus);
        });
        effectData.description += ` (当前虚招加成: +${bonus})`;
    }

    // 完美利用新加的 attBonus 参数！
    await Macros.requestContest({
        attacker: actor,
        defender: args.target,
        type: "sword",
        label: "纵横逆顺 - 剑气压制",
        attBonus: 3,
        outcome: {
            win: { text: "剑气压制成功！获得 [神虹]。", selfEffect: effectData },
            lose: { text: "压制失败。" }
        }
    });
}

await game.xjzl.api.effects.addEffect(args.target, "chanshou", 1);

if (actor.effects.some(e => e.name === "神虹")) {
    const lvl = Math.max(1, args.move.computedLevel || 1);
    const rounds = lvl; // 1 + (lvl - 1)
    const blindData = { id: "blind", duration: { rounds: rounds } };
    await game.xjzl.api.effects.addEffect(args.target, blindData);
}

if (!args.isHit) return;
await Macros.requestContest({
    attacker: actor,
    defender: args.target,
    type: "sword",
    label: "越甲三千 - 剑气碾压",
    outcome: {
        win: {
            text: "剑扫千军！你粉碎了对方的手骨。(请根据战报手动处理[骨折]部位残疾)"
        },
        lose: {
            text: "目标勉强抵挡了剑气。"
        }
    }
});

const fofa = S.arts.fofa.total || 0;
if (fofa > 0) {
    args.output.damage += fofa * 10;
    args.output.bonusDesc.push(`佛法 +${fofa * 10}`);
}

if (args.isHit) {
    // 1. 添加错骨状态
    await game.xjzl.api.effects.addEffect(args.target, "cuogu");

    // 2. 计算DC (对方每有一级佛法，难度-1)
    const targetFofa = args.target.system.arts?.fofa?.total || 0;
    const dc = Math.max(0, 15 - targetFofa);

    // 3. 获取自定义特效
    const fracture = thisItem.effects.getName("骨折");
    if (fracture) {
        // 4. 发起检定
        await Macros.requestSave({
            target: args.target,
            attacker: actor,
            type: "renxing",
            dc: dc,
            label: "抵抗骨折",
            onFail: fracture.toObject()
        });
    }
}

if (args.isHit) {
    // 从系统配置中获取禁虚数据
    const statusData = CONFIG.statusEffects.find(e => e.id === "jinxu");
    if (statusData) {
        const effectData = foundry.utils.deepClone(statusData);
        effectData.duration = { rounds: 1 };
        await game.xjzl.api.effects.addEffect(args.target, effectData);
    }
}

// 养血是系统可叠层状态，管理器会自动处理叠层逻辑
await game.xjzl.api.effects.addEffect(args.target, "yangxue");
ui.notifications.info(`${actor.name} 为 ${args.target.name} 施针疗伤，施加了 [养血]`);
